from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class Link(SchemaObject):
    rel = SchemaField(name='rel')
    href = SchemaField(name='href')

    def __init__(self, rel, href):
        self.rel = rel
        self.href = href

        super(Link, self).__init__()


class RevertObjectResponseV1(SchemaObject):
    action_id = SchemaField(name='action_id', not_null=True)
    links = SchemaField(name='links', klass=Link, optional=True)
    status = SchemaField(name='status', not_null=True)
    error_message = SchemaField(name='error_message')

    def __init__(self, action_id, links, status, error_message):
        self.action_id = action_id
        self.links = links
        self.status = status
        self.error_message = error_message

        super(RevertObjectResponseV1, self).__init__()
